import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        a.sort()

        min_val = a[0]
        max_val = a[-1]

        count_min = 0
        count_max = 0

        for x in a:
            if x == min_val:
                count_min += 1
            if x == max_val:
                count_max += 1

        if min_val == max_val:
            ans = (n * (n - 1)) // 2
        else:
            if count_min >= count_max:
                ans = (count_min * (count_min - 1)) // 2 + count_min * (n - count_min)
            else:
                ans = (count_max * (count_max - 1)) // 2 + count_max * (n - count_max)

        results.append(str(ans))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
